(function () {
  const API_KEY = "hidden";
  function callApi(path) {
    return fetch(path, { headers: { Authorization: API_KEY } });
  }
  window.mySdk = { callApi };
})();

// API_KEY is not on window — only callApi is exposed

const counter = (function () {
  let value = 0;

  function increment() { value += 1; return value; }
  function reset() { value = 0; }

  return { increment, reset, get: () => value };
})();

counter.increment(); // 1
counter.reset();
counter.get();       // 0

const logger = (function (root, factory) {
  return factory(root.console);
})(globalThis, function (console) {
  let level = "info";
  return {
    setLevel(l) { level = l; },
    log(msg) { if (level !== "silent") console.log(msg); }
  };
});
